namespace ghidra.util.filechooser;







using ghidra.util;
using utilities.util.reflection;

/**
 * A convenience implementation of FileFilter that filters out
 * all files except for those type extensions that it knows about.
 * <p>
 * Extensions are of the type "foo" (no leading dot). Case is ignored.
 * <p>
 * Example - create a new filter that filters out all files
 * but gif and jpg image files:
 * <pre>
 *     GhidraFileChooser chooser = new GhidraFileChooser();
 *     chooser.addFileFilter(ExtensionFilFilter.forExtensions("JPEG and GIF Images", "gif", "jpg"));
 *</pre>
 */
public class ExtensionFileFilter : GhidraFileFilter {

	/**
	 * Creates a {@link ExtensionFileFilter} in a varargs friendly way.
	 *
	 * @param description String description of this set of file extensions.
	 * @param exts variable length list of file extensions, without leading dot.
	 * @return new {@link ExtensionFileFilter} instance.
	 */
	public static ExtensionFileFilter forExtensions(string description, params string[] exts) {
		ExtensionFileFilter eff = new ExtensionFileFilter(exts, description);
		return eff;
	}

	private List<string> extensions;
	private string description;
	private string fullDescription;

	/**
	 * Creates a file filter that accepts the given file type.
	 * <p>
	 * Example: new ExtensionFileFilter("jpg", "JPEG Images");
	 *
	 * @param extension file extension to match, without leading dot
	 * @param description descriptive string of the filter
	 */
	public ExtensionFileFilter(string extension, string description) : this(new string[] { extension }, description)
    {
	}

	/**
	 * Creates a file filter from the given string array and description.
	 * <p>
	 * Example: new ExtensionFileFilter(String {"gif", "jpg"}, "Gif and JPG Images");
	 *
	 * @param filters array of file name extensions, each without a leading dot
	 * @param description descriptive string of the filter
	 */
	public ExtensionFileFilter(string[] filters, string description) : this(Arrays.stream(filters), description)
    {
	}

	/**
	 * Creates a file filter from the given string {@link Collection} and description.
	 * <p>
	 * Example: new ExtensionFileFilter(List.of("gif", "jpg"), "Gif and JPG Images");
	 *
	 * @param filters array of file name extensions, each without a leading dot
	 * @param description descriptive string of the filter
	 */
	public ExtensionFileFilter(Collection<string> filters, string description) : this(filters.stream(), description)
    {
	}

	/**
	 * Creates a file filter from the given string {@link Stream} and description.
	 * <p>
	 * Example: new ExtensionFileFilter(Stream.of("gif", "jpg"), "Gif and JPG Images");
	 *
	 * @param filters {@link List} of file name extensions, each without a leading dot
	 * @param description descriptive string of the filter
	 */
	private ExtensionFileFilter(Stream<string> filters, string description) {
		this.extensions = filters.map(ExtensionFileFilter.clean).collect(Collectors.toList());
		this.description = description;
	}

	private static string clean(string ext) {
		string lc = ext.toLowerCase();
		if (lc.startsWith(".")) {
			Msg.error(typeof(ExtensionFileFilter), "Extensions cannot start with '.': " + ext,
				ReflectionUtilities.createJavaFilteredThrowable());
			return lc.substring(1);
		}
		return lc;
	}

	/**
	 * Return true if this file should be shown in the directory pane,
	 * false if it shouldn't.
	 *
	 * Files that begin with "." are ignored.
	 *
	 * @see FileFilter#accept
	 */
	/* @Override */
	public bool accept(File f, GhidraFileChooserModel model) {
		if (f == null) {
			return false;
		}
		if (model.isDirectory(f)) {
			return true;
		}
		if (extensions.isEmpty()) {
			return true;
		}

		string filename = f.getName().toLowerCase();
		if (filename.startsWith(".")) {
			return false; // assuming we don't want to allow hidden files?
		}

		int n = filename.length();
		foreach (string ext in extensions) {
			if (ext.length() >= n) {
				continue; // >= since we will add the '.'
			}

			if (filename.endsWith('.' + ext)) {
				return true;
			}
		}

		return false;
	}

	/* @Override */
	public string getDescription() {
		if (fullDescription == null) {
			fullDescription = Objects.requireNonNullElse(description, "");

			// add prettified extensions to the description string
			fullDescription += " (";
			fullDescription += extensions.isEmpty()
					? "*.*"
					: extensions.stream().map(s => "*." + s).collect(Collectors.joining(","));
			fullDescription += ")";
		}
		return fullDescription;
	}
}
